INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fdf74a13-657b-49ac-9e1c-a7a3a893aa18', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$1. óra: Az év bevezetése, ismétlés, játékos bevezető$q$, $q$Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "d2f688de-63db-40cd-bf6f-a05056a1dbe4", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "b0e5e0a9-5b65-4e65-9f0d-6d980716f02f", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "ce4bbe11-199d-42e3-8e9c-2d9f26ab515b", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "c92ed6a9-e58d-46b9-8b69-5ea171f90db7", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "8884f363-bc7e-40a8-9a2a-8c57aaabbbea", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "f8b3972a-380d-4239-94ae-7113360c9ca0", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "b34b9ab1-db07-4136-b36f-efc4956ecbf9", "text": "Igaz", "isCorrect": true}, {"id": "4e4ce39b-065c-4b79-be83-8edf12442efa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4f8090b4-1a56-4e5b-9af4-4ddf8842fe17", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "c4a60df6-a5b7-4948-a815-747ed4087910", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "ad227c5c-be91-4104-bafc-a1c5a5c66a2c", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "848bbf1b-c871-47c4-bdda-7294d2b093ef", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "e4a9efab-f03e-4488-ab0e-6bcedeec000f", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "bf0d707c-748f-4d50-a54f-0fb631bbe7e5", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "a7902534-f263-4522-a556-c43d01d441f0", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "9f273ea6-af4f-40ea-ab73-512ae8c883b6", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "ed3729f2-16e7-4a74-8864-62e9edb127f4", "text": "Igaz", "isCorrect": true}, {"id": "588cef6a-fc7e-412d-ab20-0a79ab0b107d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fc96751c-499a-4870-b419-167aa20953f0", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('88e2d9b5-d1e3-42b7-b274-92e62e6879c1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$2. óra: Játékok$q$, $q$Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "45149867-9060-4cc9-a381-52d0adafa1ac", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "473e5597-9108-49df-a3e8-c0721fabd403", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "66ad518c-7e4f-47d7-8b8d-8216c24be776", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "9d0379a9-3ce9-4acb-9409-3315ed4e66d4", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "0f74a68a-db98-4bd2-a4f6-b731cd6993ed", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "8208a9af-7997-4557-8fb4-1042bfcbb262", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "281d23ca-86fb-4bc7-bbd9-b72259eef888", "text": "Igaz", "isCorrect": true}, {"id": "b3ba1c27-8af0-4679-9d5b-692833130806", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a57fa06-1277-43aa-8092-7b687aac2bff", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "ec8d6159-69ea-4a3e-a575-0cae798b76a8", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "4fd68889-18fb-427d-bb17-71b96984d3ef", "text": "Sudoku", "isCorrect": true}, {"id": "63cc18a5-d644-45d5-b241-6b44627ba666", "text": "Fócsoport", "isCorrect": false}, {"id": "6503af3a-2a85-469f-bc91-a9b248b7b1eb", "text": "Futóverseny", "isCorrect": false}, {"id": "7a41a761-18b6-4324-b517-6b9c5ad2bb06", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "0a334c5c-155f-49b5-b4ae-bf1ac8e803bc", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "15d3801e-7c80-444d-95b7-d3c800e62c0a", "text": "Igaz", "isCorrect": true}, {"id": "0b49ca5a-933e-43fa-a9f4-141de1d9bb71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7421e206-fd71-4286-8498-cc4641ef4890", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "273d7aff-f2b1-48f6-b643-72b36daaf8be", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "ff9bf4a7-b9f9-4eb4-8d59-9ba64d64ed60", "text": "Igaz", "isCorrect": true}, {"id": "da20f722-0ac3-45a9-81ed-13dcbb751a62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('917a0279-aee7-462d-a547-959ad9c78f3a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$3. óra: Év eleji diagnosztikus felmérés$q$, $q$Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "47b434ce-5bab-4979-82b4-1b6a7cf65247", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "5f2cec69-fc18-472a-a9ff-f9eac1e2cbd1", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "55390016-8f60-4552-af23-411cced18a3f", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "b8f78078-6726-4495-b45e-0077e9cae55e", "text": "2/4", "isCorrect": false}, {"id": "7dbdf942-ffbf-45a1-9ab7-28dcc94d218f", "text": "4/8", "isCorrect": false}, {"id": "88cab21c-d396-4086-a893-9f6422ef69fc", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "6920cc46-8381-4bcf-94ac-ed784ecc8bb1", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "cb5e38ad-2fc4-4a41-99d3-96cf84f4b1ef", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "e3a1ea4a-b98f-4dc6-9436-e1f58f28423a", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "df7b501e-bc77-49a4-933b-c48ac40eb671", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "7f4fa77a-e906-40dc-b511-4200cf7fddb7", "text": "Igaz", "isCorrect": true}, {"id": "06cf4e4f-2933-4f40-95c4-9ed44ab3748b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4510fbdd-f61f-4cf8-a209-9b8abf0089a8", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "74f3d64f-f33f-4d7d-806e-dd50fe0afb44", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "23759a1b-828e-4a0a-90d3-905931832efa", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "b388aecf-c325-407e-9672-6cce4308a25b", "text": "Igaz", "isCorrect": true}, {"id": "e8c28904-4da1-4bc8-a716-e45a820a099c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ae73ada-146c-4ce2-94f0-e513437e177a", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b251bc7f-ecc2-4e50-bb01-bac20528a0f9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$4. óra: Műveletek az egész számok körében$q$, $q$Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "bd2ad296-7167-4dd8-98f8-ea7219994888", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "37898555-a877-40e1-9e62-a09e6dfc379b", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "69550059-f389-44ab-bdf4-c0c5fd5c9407", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "1ef7afc5-ef00-4bd7-835b-79feab7aacbf", "text": "Igaz", "isCorrect": true}, {"id": "6722a50b-e5b9-4705-93a3-9c133fb36bd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cf562643-8c23-4761-a7c3-570804d20f69", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "903de487-c255-4b17-a766-298153ec2661", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "abf7e630-8087-4ade-aab5-65db3034fce1", "text": "-8", "isCorrect": true}, {"id": "9ba9d5be-3414-4337-ab6a-168d1e464d90", "text": "-15", "isCorrect": false}, {"id": "81005a36-9b26-4d25-b66a-d4edfd72e56f", "text": "Egyenlőek", "isCorrect": false}, {"id": "89c065f4-8006-431d-84f2-5f0c11d93bd0", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "ef58569e-1042-4d37-9583-2cdb661eb493", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "96663c2c-75b5-41b7-8a20-e789afde8282", "text": "Igaz", "isCorrect": true}, {"id": "80b86aa0-134a-4c83-a4b3-