INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('248f0697-972b-48a2-8af1-ac364c465f72', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$5. óra: Az egész számok szorzása$q$, $q$Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "9a6ca61e-b9aa-4a1b-a2b2-21b997343f96", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "278825e9-0bc4-46ff-9354-bf4282406d6b", "text": "Pozitív (+)", "isCorrect": true}, {"id": "1ae211e4-d958-4110-b5ed-fa73c9603e26", "text": "Negatív (-)", "isCorrect": false}, {"id": "938f991b-b735-4004-99ac-a5dd0e522d20", "text": "Mindig 0", "isCorrect": false}, {"id": "340f974b-aaff-4845-9992-5d6104057532", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "3ba5f9fd-f085-4325-a967-fcb06f47e752", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "0de0f7dd-f836-4694-82dc-7c8598c8d09e", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "ca0f71b2-f4c5-4f9d-8292-ce1ee169e9b4", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "9e0e517c-a4a1-4b7c-9d13-77e9b673173c", "text": "Igaz", "isCorrect": true}, {"id": "c609df0c-f788-4500-9566-956c05cb766e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ab15d712-3c86-41bc-bf8f-3fe8afb16829", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "44b769c0-eb2d-4a76-95e9-6d36b8b8ad55", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "d19909d6-b646-41c9-a7eb-04b5c8ebdc94", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "4d3962d4-5320-42e7-95cf-dc6508733e1d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e1784fe-2a8e-4021-b4e7-080ce330bce7", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2a945105-b053-411e-97ae-51e52671afed', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$6. óra: Gyakorlóóra: az egész számok szorzása$q$, $q$Több tényező előjelének meghatározása, szorzások gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "c07b07c2-b98f-4f10-8b6f-b264e34032f6", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "14586a0b-d5f4-433c-9448-bb746b9009e4", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "4cddae7b-2b45-4fff-aade-33022f304633", "text": "Pozitív", "isCorrect": true}, {"id": "b59279ca-b078-4e15-b0ac-1e45ef9e1a53", "text": "Negatív", "isCorrect": false}, {"id": "ed55e25b-d06e-4036-b398-be312d928e63", "text": "Nulla", "isCorrect": false}, {"id": "726d8c0b-619e-4445-88b8-7a0390c3a31a", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "d4792626-7f9b-4b1e-bad2-a1bf01d0ad1f", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e89bedaa-c981-46e1-b027-e93babd97a83", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "7648d87b-482d-4aa8-8352-9f396511da78", "text": "Igaz", "isCorrect": true}, {"id": "b806526f-5dee-4e13-bf85-5de94cc2bbd1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ab50479c-97c2-4dae-9523-250b2d463fa0", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "1b6c12df-0f01-46d1-bd9e-8cf05ca5ca0c", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "5ee038ae-2785-45e1-8f2e-ba2f35c4506e", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "4e11841f-d98b-4c02-856a-f9ff67f70acf", "text": "Igaz", "isCorrect": true}, {"id": "9115d0fc-4b90-42ad-a37d-8d9824b7e43f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('abc23b41-2299-415d-bd8f-5a87e48c7e5b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$7. óra: Az egész számok osztása$q$, $q$Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "60c4dd91-f19e-4e73-9b0f-f2036bf33b4c", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "2a934143-3b66-4a39-97a4-85b5290b9f88", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "fdaae131-a107-4e0b-b266-7eb3e48e1a65", "text": "Mindig negatív", "isCorrect": false}, {"id": "b82996b3-273b-43a0-b01c-630d476a9812", "text": "Mindig pozitív", "isCorrect": false}, {"id": "ec6ce71a-b2c9-493a-a90d-0b8439a94435", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "100876a4-616d-4314-9489-1ab9a7c09e22", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "80c4b277-1dd1-4746-bafb-53b1373ba53f", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c96e89c6-6788-4eaa-8ab4-9d91d4ee0cb1", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "4f6ea781-d126-4d84-ba57-ac11616105f8", "text": "Igaz", "isCorrect": true}, {"id": "485806cb-6b6f-41e8-9d4c-82fff02d71af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5f64137-8f82-4505-8da1-49cd8b340cf4", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "db5cae2d-5caa-416d-9904-8465589a686a", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "f19f79b1-6332-41bf-b41b-b3e04537b2c3", "text": "Igaz", "isCorrect": true}, {"id": "8dcc2d22-3b6c-4ad0-9218-fdba78bf6084", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3acbfb18-de71-4fb3-bbb9-094f04032408", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3b3dd43a-ccb8-4ae3-ac69-8cc803955bf2', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$8. óra: Az egész számok osztásának gyakorlása$q$, $q$Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "90346e42-89dd-4ed8-8460-07f5877a0955", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "8b7e190c-a672-4e04-9a5b-213a47b90a02", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "c74d70da-0260-42ad-88c1-f767afd827b6", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "81c48d1d-86aa-4861-b216-0da5e2910755", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "d03e56e1-a18e-43c2-8fd1-1388147eb8be", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "ad0c312a-d19b-4e0d-bbf0-23bf14688eb9", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "c9d7acde-e073-4ee5-aeaa-45d20d108250", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "94d25f62-2a01-487a-98b9-e96f100565a8", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "0031badb-fbad-48a3-b193-7ac41ab8d17b", "text": "Igaz", "isCorrect": true}, {"id": "f3d0b444-3716-42d9-a3e1-71986cf2912a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "01ed19e6-a3e6-4796-840b-538533d2fcc7", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "6ccf89a3-2339-43fa-b7d4-7add91413e9d", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "bcd028b5-fb42-4e64-a565-8643400f7067", "text": "Igaz", "isCorrect": true}, {"id": "250cc534-12af-4cd4-84f2-9224198bb0c0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7cf26306-d72b-42bd-b9dd-3067cc8de9e6", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e33a0b94-69b7-413f-955c-38000e70b60c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$9. óra: Hány eset van? Számoljuk össze!$q$, $q$Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "23b9ed58-909f-45a8-b3cc-1984c339cc6a", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "9212d971-b8b1-45f2-80d0-bbc3329abf60", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "720cc9c4-b25c-4571-bb10-20b1f3063ae5", "text": "Szögmérőt", "isCorrect": false}, {"id": "aadd1218-1619-4f04-88d5-d58e4c37aafa", "text": "Körzőt", "isCorrect": false}, {"id": "483be11c-508d-47b3-9965-a030850ed02f", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "ab5ffc48-ad07-4355-9212-05ca68dfe814", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "2e55ff69-4391-4915-8fa4-b87075699689", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "d6876409-2288-4784-9144-9116999bb982", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "45427c71-5e97-4513-a6b9-25fcf0f06f76", "text": "Igaz", "isCorrect": true}, {"id": "cb9a97d7-1b4c-4845-b2d5-9a2bc60e1eec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d017bc67-f9a5-4ccf-a735-ea7a88ef5d21", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "dfe76dd7-87f1-44fd-b910-4707bea020e2", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "de201e04-54a3-4f04-91e4-d46e96208918", "text": "Igaz", "isCorrect": false}, {"id": "f1790d63-6b63-4b0a-a34b-71560eae0a6c", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "0e5c668c-b6c4-4eeb-afe1-41c4f427ec91", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('68f9a9f7-297a-4131-814a-be7666472563', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!$q$, $q$Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "fa447318-8729-496f-a453-287ce39cd771", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "58230baf-b25b-4f29-bb9a-1333f85d48fb", "text": "2 (12, 32)", "isCorrect": true}, {"id": "839d0ad0-0469-47ea-b5a9-247048b2c805", "text": "3", "isCorrect": false}, {"id": "60bf8c32-cadd-4695-83dc-796a1f942eb3", "text": "4", "isCorrect": false}, {"id": "f3e5a588-d1f5-4465-bc78-8fca7c28bf3a", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "0f0026c9-01aa-431b-a7a7-61df7f9af3fe", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "2cb9c856-3c0f-4c69-a375-2291c2a027fa", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "5025266e-6bc4-4ac8-8232-dcb4494cb56e", "text": "Igaz", "isCorrect": true}, {"id": "e8c30c53-6007-4403-bca2-5b3a8b7c2359", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3033a47a-f15f-4f6b-885e-a8c7bdbd99f2", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "8ea5f8a0-7cd7-42cb-b0af-8c9c8898b978", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "69559fc7-285e-46db-8d60-6d6ca90fba77", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "5b7ecfcc-c38a-4045-b00f-0cf986d23344", "text": "Igaz", "isCorrect": true}, {"id": "fa5e9352-5538-408f-b3bc-bbe04d7606fd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f43dca1e-2f94-44c5-afab-c2c8789f96fe", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;